      videos: { kicker: "Tazama na Ujifunze", title: "Taarifa za Afya kwa Video", subtitle: "Unapendelea kutazama? Wataalamu wetu wa afya wanaelezea mada muhimu kwa video rahisi kueleweka.", watchNow: "Tazama Video", vid1Title: "Nini cha kutarajia wakati wa ujauzito", vid1Time: "3:45", vid2Title: "Jinsi ya kunyonyesha kwa usahihi", vid2Time: "4:20", vid3Title: "Kutambua dalili za msongo wa mawazo", vid3Time: "5:10" },
      howItWorks: { kicker: "Jinsi inavyofanya kazi", title: "Kupata msaada ni rahisi", subtitle: "Hatua tatu za kupata msaada wa afya unaoaminika kwa ajili yako na familia yako.", step1Title: "Fungua akaunti yako", step1Description: "Jiandikishe kwa chini ya dakika moja kwa jina lako, simu, na lugha unayopendelea.", step2Title: "Chagua lugha yako", step2Description: "Tumia AfyaLink kwa Kiingereza, Kiswahili, au Kisomali — chochote kinachokufaa zaidi.", step3Title: "Pata huduma na msaada", step3Description: "Vinjari mada za afya, pata vituo, na uweke miadi yote mahali pamoja." },
      testimonial: { kicker: "Kutoka kwa jamii yetu", quote: "Kabla ya AfyaLink, nililazimika kusafiri mbali kupata majibu kuhusu ujauzito wangu. Sasa nasoma taarifa zinazoaminika kwa Kiswahili, napata kliniki iliyo karibu, na kuweka miadi yangu kwa wakati. Imefanya tofauti ya kweli kwa familia yangu.", author: "Halima A.", role: "Mama wa watoto wawili, Kaunti ya Garissa" },
      faq: { kicker: "Una Maswali?", title: "Maswali Yanayoulizwa Mara Kwa Mara", subtitle: "Kila kitu unachohitaji kujua kuhusu AfyaLink. Hupati jibu unalotafuta? Tafadhali wasiliana na timu yetu.", contactCta: "Wasiliana na Msaada", q1: "Je, AfyaLink ni bure kutumia?", a1: "Ndio, AfyaLink ni bure 100% kwa wanajamii wote. Dhamira yetu ni kutoa taarifa za afya zinazopatikana na msaada kwa kila mtu Kaskazini-Mashariki mwa Kenya.", q2: "Je, taarifa zangu za afya ni za siri?", a2: "Kabisa. Tunazingatia faragha yako kwa umakini mkubwa. Data yako ya kibinafsi na miadi huhifadhiwa kwa usalama na hazishirikiwi na wahusika wengine bila idhini yako.", q3: "Je, ninaweza kutumia AfyaLink kwa lugha yangu ya nyumbani?", a3: "Ndio! Jukwaa limefanywa tafsiri kikamilifu katika Kiingereza, Kiswahili, na Kisomali. Unaweza kubadilisha lugha wakati wowote ukitumia menyu iliyo juu.", q4: "Ninawezaje kupata kliniki iliyo karibu?", a4: "Unaweza kutumia saraka yetu ya 'Vituo vya Afya' kutafuta kliniki, hospitali, na maduka ya dawa karibu na eneo lako. Pia tunatoa maelezo yao ya mawasiliano.", q5: "Je, ninahitaji akaunti kuweka miadi?", a5: "Ndio, kuunda akaunti ya bure kunakuwezesha kuweka miadi kwa usalama, kufuatilia historia yako, na kupokea vikumbusho muhimu ili usikose ziara." },
