      howItWorks: { kicker: "Sida ay u shaqeyso", title: "Caawinaad helista waa fududahay", subtitle: "Saddex tallaabo oo lagu helo taageero caafimaad oo lagu kalsoonaan karo adiga iyo qoyskaaga.", step1Title: "Samee akoonkaaga", step1Description: "Isdiiwaangeli daqiiqad ka yar adigoo isticmaalaya magacaaga, telefoonkaaga, iyo luqadda aad doorbidayso.", step2Title: "Dooro luqaddaada", step2Description: "Isticmaal AfyaLink Ingiriisi, Kiswahili, ama Soomaali — wax kasta oo kugu habboon.", step3Title: "Hel daryeel & taageero", step3Description: "Baadh mawduucyada caafimaadka, raadi xarumo, oo qabso ballamo dhammaantood hal meel." },
      testimonial: { kicker: "Bulshadeenna ka timid", quote: "AfyaLink ka hor, waxaan u safri jiray meel fog si aan u helo jawaabo ku saabsan uurkeyga. Hadda waxaan akhriyaa macluumaad lagu kalsoonaan karo oo Soomaali ah, waxaan helaa rugta ugu dhow, oo waqtigeeda ayaan ballamahayga qabsadaa. Dhab ahaantii wax weyn ayay u beddeshay qoyskayga.", author: "Xaliimo A.", role: "Hooyo laba carruur ah, Gobolka Garissa" },
      faq: { kicker: "Su'aalo Ma Qabtaa?", title: "Su'aalaha Inta Badan La Weydiiyo", subtitle: "Wax kasta oo aad u baahan tahay inaad ka ogaato AfyaLink. Ma heli kartid jawaabta aad raadinayso? Fadlan la xiriir kooxdayada.", contactCta: "La Xiriir Taageerada", q1: "AfyaLink ma bilaash baa in la isticmaalo?", a1: "Haa, AfyaLink waa 100% bilaash xubnaha bulshada oo dhan. Hadafkayagu waa inaan bixino macluumaad caafimaad oo la heli karo iyo taageero qof kasta oo ku nool Waqooyi-Bari Kenya.", q2: "Macluumaadkayga caafimaadka ah ma qarsoodi baa?", a2: "Gabi ahaanba. Waxaan si dhab ah u qaadnaa asturnaantaada. Xogtaada shakhsi ahaaneed iyo ballamahaaga si ammaan ah ayaa loo kaydiyaa oo waligood lama wadaagaan dhinacyo kale fasax la'aan.", q3: "Ma isticmaali karaa AfyaLink luqaddayda hooyo?", a3: "Haa! Madasha si buuxda ayaa loo tarjumay Ingiriisi, Kiswahili, iyo Soomaali. Waad beddeli kartaa luqadda wakhti kasta adigoo isticmaalaya liiska sare.", q4: "Sidee ku helaa rug caafimaad oo dhow?", a4: "Waxaad isticmaali kartaa hagaha 'Xarumaha Caafimaadka' si aad u raadiso rugo, isbitaallo, iyo farmashiyo ku dhow halka aad joogto. Waxaan sidoo kale bixinaa faahfaahin xiriir.", q5: "Ma u baahanahay akoon si aan u qabsado ballan?", a5: "Haa, abuurista akoon bilaash ah waxay kuu ogolaanaysaa inaad si ammaan ah u qabsato ballamo, u la socoto taariikhdaada, oo aad hesho xusuusin muhiim ah si aadan u seegin booqasho." },
      cta: { title: "Ma diyaar u tahay inaad bilowdo?", description: "Samee akoon bilaash ah si aad u kaydiso ballamo, u dejiso xusuusin, oo u hesho macluumaad caafimaad luqaddaada.", primary: "Samee akoon bilaash", secondary: "Nala hadal" },
